import type { ImageMetadata } from 'astro'

/**
 * Client wall ("Our clients"). Shared by EN and ES, sorted alphabetically.
 * Logos are trimmed webp files in `src/assets/clients/logos/<slug>.webp`; most come from
 * `apps/web/src/assets/clientes/logos` (generated by its `build-client-logos.mjs`).
 * To add a client: drop its webp in that folder and add one entry here.
 */
const clients = [
  { slug: 'aquafresh', name: 'Aquafresh' },
  { slug: 'atsa', name: 'ATSA Airlines' },
  { slug: 'black-decker', name: 'Black+Decker' },
  { slug: 'cadence', name: 'Cadence Bank' },
  { slug: 'claro', name: 'Claro' },
  { slug: 'construplan', name: 'Construplan' },
  { slug: 'dewalt', name: 'DEWALT', boxed: true },
  { slug: 'grin', name: 'Grin' },
  { slug: 'grupo-pracda', name: 'Grupo Pracda', boxed: true },
  { slug: 'irwin', name: 'IRWIN Tools', boxed: true },
  { slug: 'jw-marriott', name: 'JW Marriott' },
  { slug: 'movistar', name: 'Movistar' },
  { slug: 'nadira', name: 'Nadira' },
  { slug: 'pringles', name: 'Pringles' },
  { slug: 'sensodyne', name: 'Sensodyne' },
  { slug: 'sgs', name: 'SGS' },
  { slug: 'siemens', name: 'Siemens' },
  { slug: 'stanley', name: 'Stanley', boxed: true },
  { slug: 'stanley-black-decker', name: 'Stanley Black & Decker', boxed: true },
  { slug: 'tedx', name: 'TEDx' },
  { slug: 'televisa', name: 'Televisa' },
  { slug: 'tripadvisor', name: 'Tripadvisor' },
  { slug: 'usaid', name: 'USAID' },
  { slug: 'vive-paracas', name: 'Vive Paracas' },
] as const satisfies readonly { slug: string, name: string, boxed?: boolean }[]

const files = import.meta.glob<{ default: ImageMetadata }>('../assets/clients/logos/*.webp', { eager: true })

// Target visual area (px²): width = √(area · aspect) makes a 6:1 wordmark and a square mark
// weigh about the same. Logos on a solid block read heavier, so they get less area.
const AREA = 5600
const BOXED_AREA = AREA * 0.6
const MAX_WIDTH = 150

export interface ClientLogo {
  name: string
  image: ImageMetadata
  /** Rendered width in px at full size (sm and up). */
  width: number
}

export const clientLogos: ClientLogo[] = clients.map((client) => {
  const image = files[`../assets/clients/logos/${client.slug}.webp`]?.default
  if (!image)
    throw new Error(`Missing client logo: src/assets/clients/logos/${client.slug}.webp`)
  const area = 'boxed' in client && client.boxed ? BOXED_AREA : AREA
  const width = Math.round(Math.min(MAX_WIDTH, Math.sqrt(area * (image.width / image.height))))
  return { name: client.name, image, width }
})
